const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    var regionCenter = ee.Geometry.Point([121.5654, 25.0330]);
    var region = regionCenter.buffer(20000).bounds(); // ~Taipei area
    var scale = 1000;
    var totalPx = ee.Image(1).rename('ones')
      .reduceRegion({reducer: ee.Reducer.count(), geometry: region, scale: scale, maxPixels: 1e9})
      .get('ones');

    // Time windows
    var winStart2016 = '2016-01-17';
    var winEnd2016 = '2016-01-25'; // end is exclusive
    var baselineYears = ee.List.sequence(2001, 2010).getInfo();

    // Collections to try (primary first)
    var collIds = ['MODIS/061/MCD11A2', 'MODIS/061/MOD11A2', 'MODIS/061/MYD11A2'];

    function maskLSTDayC(img) {
      var qc = img.select('QC_Day');
      var produced = qc.bitwiseAnd(3).lt(2); // bits 0-1: 00 or 01
      var lstErrOK = qc.rightShift(6).bitwiseAnd(3).lt(2); // bits 6-7: <=2K
      var mask = produced.and(lstErrOK);
      var lstC = img.select('LST_Day_1km').multiply(0.02).subtract(273.15).rename('LST_Day_C');
      return lstC.updateMask(mask);
    }

    async function fetchImageForWindow(start, end) {
      for (let i = 0; i < collIds.length; i++) {
        let id = collIds[i];
        let col = ee.ImageCollection(id)
          .filterDate(start, end)
          .filterBounds(region)
          .select(['LST_Day_1km', 'QC_Day']);
        let sz = await col.size().getInfo();
        if (sz > 0) {
          // In rare case >1, take mean to be robust
          let img = ee.Image(col.mean()).copyProperties(col.first(), ['system:time_start']);
          return {image: img, source: id, count: sz};
        }
      }
      // Try slightly widened window
      let startWide = ee.Date(start).advance(-1, 'day').format('YYYY-MM-dd').getInfo();
      let endWide = ee.Date(end).advance(1, 'day').format('YYYY-MM-dd').getInfo();
      for (let i = 0; i < collIds.length; i++) {
        let id = collIds[i];
        let col = ee.ImageCollection(id)
          .filterDate(startWide, endWide)
          .filterBounds(region)
          .select(['LST_Day_1km', 'QC_Day']);
        let sz = await col.size().getInfo();
        if (sz > 0) {
          let img = ee.Image(col.mean()).copyProperties(col.first(), ['system:time_start']);
          return {image: img, source: id, count: sz};
        }
      }
      return {image: null, source: null, count: 0};
    }

    // 2. Data Acquisition & Check
    // 2016 window
    let f2016 = await fetchImageForWindow(winStart2016, winEnd2016);
    if (!f2016.image) {
      console.log('2016 Images: 0');
      console.log('Baseline Images: 0');
      console.log('C1');
      return;
    }
    let img2016C = maskLSTDayC(f2016.image);

    // Baseline (2001-2010)
    let baseImgs = [];
    let baseSources = {};
    for (let y of baselineYears) {
      let s = `${y}-01-17`;
      let e = `${y}-01-25`;
      let f = await fetchImageForWindow(s, e);
      if (f.image) {
        baseImgs.push(maskLSTDayC(f.image));
        baseSources[f.source] = true;
      }
    }
    let baseCount = baseImgs.length;
    if (baseCount === 0) {
      console.log(`2016 Images: ${f2016.count} (${f2016.source})`);
      console.log('Baseline Images: 0');
      console.log('C1');
      return;
    }
    let baseMeanImg = ee.ImageCollection(baseImgs).mean().rename('LST_Day_C');

    // 3. Processing: Pixel counts to detect C2
    let totalPxN = await ee.Number(totalPx).getInfo();
    let valid2016 = await img2016C.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: scale,
      maxPixels: 1e9
    }).get('LST_Day_C').getInfo();
    valid2016 = valid2016 || 0;

    let validBase = await baseMeanImg.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: scale,
      maxPixels: 1e9
    }).get('LST_Day_C').getInfo();
    validBase = validBase || 0;

    if (valid2016 === 0 || validBase === 0) {
      console.log(`2016 Images: ${f2016.count} (${f2016.source})`);
      console.log(`Baseline Images: ${baseCount} (${Object.keys(baseSources).join('+')})`);
      console.log(`2016 Valid Px: ${valid2016}/${totalPxN} (${(100*(valid2016/Math.max(1,totalPxN))).toFixed(1)}%)`);
      console.log(`Base Valid Px: ${validBase}/${totalPxN} (${(100*(validBase/Math.max(1,totalPxN))).toFixed(1)}%)`);
      console.log('C2');
      return;
    }

    // 4. Calculation: Mean LST (Celsius)
    let mean2016 = await img2016C.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: region,
      scale: scale,
      maxPixels: 1e9
    }).get('LST_Day_C').getInfo();

    let meanBase = await baseMeanImg.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: region,
      scale: scale,
      maxPixels: 1e9
    }).get('LST_Day_C').getInfo();

    // 5. Validation & Final Answer
    let invalid = (mean2016 === null || meanBase === null || !isFinite(mean2016) || !isFinite(meanBase) ||
                   mean2016 < -100 || mean2016 > 100 || meanBase < -100 || meanBase > 100);
    console.log(`Region: Taipei 20km buffer; scale=${scale}m`);
    console.log(`2016 Images: ${f2016.count} (${f2016.source})`);
    console.log(`Baseline Images: ${baseCount} (${Object.keys(baseSources).join('+')})`);
    console.log(`2016 Valid Px: ${valid2016}/${totalPxN} (${(100*valid2016/totalPxN).toFixed(1)}%)`);
    console.log(`Base Valid Px: ${validBase}/${totalPxN} (${(100*validBase/totalPxN).toFixed(1)}%)`);
    console.log(`2016 LST_C: ${mean2016.toFixed(2)}`);
    console.log(`Base LST_C: ${meanBase.toFixed(2)}`);
    console.log(`Delta (2016 - base): ${(mean2016 - meanBase).toFixed(2)} C`);

    if (invalid) {
      console.log('C3');
    } else if (mean2016 < meanBase) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
